import{_ as l,C as i,o as r,c as s,a2 as e,b as p,w as t,a as n,E as d,a3 as E}from"./chunks/framework.DZUUNQ77.js";const b=JSON.parse('{"title":"快速使用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1784063681000}'),u={name:"guide/quick-start.md"};function A(c,a,h,g,m,B){const o=i("Mermaid");return r(),s("div",null,[a[1]||(a[1]=e('<h1 id="快速使用" tabindex="-1">快速使用 <a class="header-anchor" href="#快速使用" aria-label="Permalink to &quot;快速使用&quot;">​</a></h1><p>这一篇面向“我只是想用起来”的读者，覆盖安装、装 App、装模块、激活、重启的完整流程。原理部分请移步<a href="./../architecture/overview">架构总览</a>。</p><h2 id="使用流程总览" tabindex="-1">使用流程总览 <a class="header-anchor" href="#使用流程总览" aria-label="Permalink to &quot;使用流程总览&quot;">​</a></h2>',3)),(r(),p(E,null,{default:t(()=>[d(o,{id:"mermaid-9",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%8B%E8%BD%BD%20APK%20%E5%AE%89%E8%A3%85%E5%88%B0%E6%89%8B%E6%9C%BA%3Cbr%2F%3E(Android%205.0~10.0)%22%5D%20--%3E%20B%5B%22%E8%A3%85%E7%9B%AE%E6%A0%87%20App%20%E8%BF%9B%20VirtualXposed%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%A3%85%20Xposed%20%E6%A8%A1%E5%9D%97%E8%BF%9B%20VirtualXposed%22%5D%0A%20%20C%20--%3E%20D%7B%22App%20%E4%B8%8E%E6%A8%A1%E5%9D%97%E9%83%BD%E5%9C%A8%3Cbr%2F%3EVirtualXposed%20%E5%86%85%E9%83%A8%3F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20FAIL%5B%22Hook%20%E4%B8%8D%E7%94%9F%E6%95%88%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22Xposed%20Installer%20%E5%8B%BE%E9%80%89%E6%A8%A1%E5%9D%97%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%AE%BE%E7%BD%AE%E9%87%8C%E7%82%B9%20Reboot%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%A8%A1%E5%9D%97%E7%94%9F%E6%95%88%22%5D%0A%20%20FAIL%20-.-%3E%7C%22%E9%87%8D%E6%96%B0%E6%A3%80%E6%9F%A5%E5%AE%89%E8%A3%85%E4%BD%8D%E7%BD%AE%22%7C%20B%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<div class="warning custom-block"><p class="custom-block-title">商用警告</p><p>本项目使用的 VirtualApp <strong>不允许用于商业用途</strong>，且仓库内 VirtualApp 版本已过时。商业需求请向原作者 Lody 申请商业授权。本站内容仅供学习研究。</p></div><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><ol><li>在 <a href="https://github.com/android-hacker/VirtualXposed/releases" target="_blank" rel="noreferrer">release 页面</a> 下载最新的 APK，安装到手机。</li><li>确认系统版本在 <strong>Android 5.0 ~ 10.0</strong> 之间（更高版本可能不兼容）。</li></ol><p>如果你要用 GameGuardian（GG 修改器），需要下载带 <code>For_GameGuardian</code> 后缀的<strong>专版</strong>，普通版不行。</p><h2 id="装-app-与装模块" tabindex="-1">装 App 与装模块 <a class="header-anchor" href="#装-app-与装模块" aria-label="Permalink to &quot;装 App 与装模块&quot;">​</a></h2><p>打开 VirtualXposed，点首页底部的抽屉按钮（或长按屏幕），进入“添加应用”。</p><p>有三种安装方式：</p><ol><li><strong>克隆已装 App</strong>：第一页列出系统里已安装的 App，直接复制一份进来。</li><li><strong>从 APK 文件安装</strong>：第二页扫描 sdcard 上的 APK 文件。</li><li><strong>外部文件选择器安装</strong>：用浮动按钮选任意 APK。</li></ol><div class="danger custom-block"><p class="custom-block-title">关键规则</p><p><strong>目标 App 和 Xposed 模块都必须装在 VirtualXposed 内部。</strong></p><p>以下三种组合<strong>都不会生效</strong>：</p><ul><li>目标 App 装系统里 + 模块装 VirtualXposed 里</li><li>目标 App 装 VirtualXposed 里 + 模块装系统里</li><li>两者都装系统里</li></ul><p>原因见<a href="./../architecture/overview">架构总览</a>：模块的 Hook 只对和它跑在同一个虚拟进程里的 App 有效。</p></div><p>Xposed 模块除了用上面三种方式装，也可以通过 VirtualXposed 内置的 Xposed Installer 安装管理，用法和普通 Xposed Installer 一样。</p><h2 id="激活模块" tabindex="-1">激活模块 <a class="header-anchor" href="#激活模块" aria-label="Permalink to &quot;激活模块&quot;">​</a></h2><p>在 VirtualXposed 里打开 Xposed Installer → 进入模块页 → 勾选你要用的模块。</p><h2 id="重启" tabindex="-1">重启 <a class="header-anchor" href="#重启" aria-label="Permalink to &quot;重启&quot;">​</a></h2><p>激活后<strong>不需要重启手机</strong>。在 VirtualXposed 首页 → 设置 → 点 <code>Reboot</code>，VirtualXposed 会快速重启，模块即生效。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>模块没生效？</strong> 99% 是因为目标 App 或模块没装在 VirtualXposed 内部，重新检查安装位置。</li><li><strong>App 闪退？</strong> 可能是 VirtualXposed 版本与系统不兼容，或目标 App 有虚拟环境检测。</li><li><strong>杀毒软件报警？</strong> VirtualXposed 确实具备操作其它应用的能力，部分引擎会误报。代码开源可自查；仍不放心可使用 0.8.7 版本（该版本未被报毒）。</li></ul><h2 id="亲测可用的模块-节选" tabindex="-1">亲测可用的模块（节选） <a class="header-anchor" href="#亲测可用的模块-节选" aria-label="Permalink to &quot;亲测可用的模块（节选）&quot;">​</a></h2><p>完整清单见仓库 <a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/main/CHINESE.md" target="_blank" rel="noreferrer">CHINESE.md</a>，这里列几类典型：</p><ul><li><strong>隐私/去广告</strong>：XPrivacyLua、Minminguard、YouTube AdAway、大圣净化</li><li><strong>微信增强</strong>：微X模块、微信增强插件、微信巫师、MDWechat（资源 Hook 部分 limited）</li><li><strong>QQ 增强</strong>：QX模块、QQ精简模块、QQ斗图神器</li><li><strong>设备/位置</strong>：应用变量（机型伪装）、模拟位置（虚拟定位）、步数修改器</li><li><strong>其它</strong>：音量增强器、微信学英语、情迁抢包、指纹支付</li></ul><p>真正能用的远不止这些，可以自行测试。</p>',20))])}const D=l(u,[["render",A]]);export{b as __pageData,D as default};
